async function orderingView(){
 $('#view').innerHTML=page('WhatsApp ordering assistant.','Let customers build a basket, review the bill and explicitly confirm their order.')+'<div class="panel" id="ordering-state">Loading assistant…</div>';
 try{const state=await api('/ordering');if(view!=='ordering')return;
 $('#ordering-state').innerHTML=`<div class="panel-head"><h3>Automatic service replies</h3>${pill(state.enabled?'Enabled':'Disabled')}</div><p>The assistant replies only to incoming customer messages on a connected WhatsApp account. It does not subscribe customers to marketing or collect payment.</p><form id="ordering-config"><label class="check"><input type="checkbox" name="enabled" ${state.enabled?'checked':''}>Enable the ordering assistant for this store</label><button class="btn">Save assistant setting</button></form><div class="note">Start with ORDER 2 x Milk, 1 x Rice. Use exact product names; ambiguous products and pack sizes are clarified. Delivery requires configured 6-digit service postcodes. Reply HUMAN for staff, EDIT to restart, or CANCEL to abandon an unsubmitted basket.</div>`;
 $('#ordering-config').onsubmit=async e=>{e.preventDefault();try{await api('/ordering/config','POST',{enabled:$('[name=enabled]',e.target).checked});store=await api('/store');toast('Assistant setting saved');orderingView()}catch(e){toast(e.message)}};
 $('#view').insertAdjacentHTML('beforeend',`<div class="panel"><div class="panel-head"><h3>Customer conversations</h3><button class="btn secondary small" id="refresh-ordering">Refresh</button></div>${table(['PHONE','CHECKOUT STAGE','ITEMS','ORDER','LAST ACTIVITY',''],state.sessions.map(s=>row([esc(s.phone),pill(s.phase),s.items?.length||0,esc(s.orderNumber||'Not submitted'),date(s.updatedAt),s.phase==='human'?'Staff handover':`<button class="btn small secondary" data-handover="${esc(s.phone)}">Pause for staff</button>`])))}</div><div class="panel"><h3>Test the conversation safely</h3><p>This simulator uses a private copy of your products and store rules. No WhatsApp messages are sent and no real customers, orders or stock are changed.</p>${!store.products.length?'<div class="note warning">Add products before testing product matching. Your current catalogue is empty.</div>':''}<form id="ordering-simulator"><label>Customer messages, one per line<textarea id="simulation-messages" rows="10" style="min-height:220px">${esc(['ORDER 1 x '+(store.products[0]?.name||'Milk'),'PICKUP','Test Customer','TOMORROW','1','1','CONFIRM'].join('\n'))}</textarea></label><button class="btn secondary">Run simulation</button></form><div id="simulation-result"></div></div>`);
 $('#refresh-ordering').onclick=orderingView;$$('[data-handover]').forEach(b=>b.onclick=async()=>{try{await api('/ordering/pause','POST',{phone:b.dataset.handover});orderingView();toast('Automatic ordering paused for this conversation')}catch(e){toast(e.message)}});
 $('#ordering-simulator').onsubmit=async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{const messages=$('#simulation-messages').value.split('\n').map(x=>x.trim()).filter(Boolean);const result=await api('/ordering/simulate','POST',{messages});$('#simulation-result').innerHTML='<div class="note">Simulation complete. '+result.createdOrders.length+' test order(s) created in the temporary copy only.</div>'+result.transcript.map(t=>`<div class="message out">${esc(t.customer)}</div><div class="message">${esc(t.assistant)}</div>`).join('')}catch(err){toast(err.message)}finally{button.disabled=false}};
 }catch(e){if($('#ordering-state'))$('#ordering-state').textContent=e.message}
}
const automationsBeforeStep5=automations;
automations=async function(){await automationsBeforeStep5();if(view==='automations'){$('.panel',$('#view')).insertAdjacentHTML('afterbegin','<div class="card-row"><span class="row-icon">◉</span><div><b>Customer ordering assistant</b><small>Product clarification, checkout confirmation and staff handover</small></div><button class="btn" id="open-ordering">Configure</button></div>');$('#open-ordering').onclick=()=>navigate('ordering')}};
